// app/verify/page.tsx
'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/contexts/auth-context';
import verificationService from '@/services/verification.service';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Mail, Phone, CheckCircle2, AlertCircle } from 'lucide-react';
import Link from 'next/link';

export default function VerifyPage() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuth();
  
  const [emailCode, setEmailCode] = useState('');
  const [phoneCode, setPhoneCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [status, setStatus] = useState({
    email_verified: false,
    phone_verified: false,
  });

  // Charger le statut de vérification
  useEffect(() => {
    if (!authLoading && user) {
      loadVerificationStatus();
      // Envoyer automatiquement les codes à l'arrivée sur la page
      sendInitialCodes();
    } else if (!authLoading && !user) {
      router.push('/login');
    }
  }, [authLoading, user]);

  const loadVerificationStatus = async () => {
    try {
      const data = await verificationService.getVerificationStatus();
      setStatus(data);
      
      // Si tout est vérifié, rediriger vers les préférences
      if (data.email_verified && data.phone_verified) {
        router.push('/preferences');
      }
    } catch (err) {
      console.error('Erreur chargement statut:', err);
    }
  };

  const sendInitialCodes = async () => {
    try {
      // Envoyer le code email si pas vérifié
      if (!status.email_verified) {
        await verificationService.sendEmailVerification();
      }
      // Envoyer le code SMS si pas vérifié
      if (!status.phone_verified) {
        await verificationService.sendPhoneVerification();
      }
      setSuccess('Codes de vérification envoyés!');
    } catch (err: any) {
      console.error('Erreur envoi codes:', err);
    }
  };

  const handleVerifyEmail = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccess(null);

    try {
      await verificationService.verifyEmail(emailCode);
      setSuccess('Email vérifié avec succès!');
      await loadVerificationStatus();
      setEmailCode('');
    } catch (err: any) {
      setError(err.message || 'Erreur lors de la vérification');
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyPhone = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccess(null);

    try {
      await verificationService.verifyPhone(phoneCode);
      setSuccess('Téléphone vérifié avec succès!');
      await loadVerificationStatus();
      setPhoneCode('');
    } catch (err: any) {
      setError(err.message || 'Erreur lors de la vérification');
    } finally {
      setLoading(false);
    }
  };

  const handleResendEmail = async () => {
    setLoading(true);
    setError(null);
    try {
      await verificationService.sendEmailVerification();
      setSuccess('Code email renvoyé!');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleResendPhone = async () => {
    setLoading(true);
    setError(null);
    try {
      await verificationService.sendPhoneVerification();
      setSuccess('Code SMS renvoyé!');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSkip = () => {
    router.push('/preferences');
  };

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#FF5722] mx-auto"></div>
          <p className="mt-4 text-gray-600">Chargement...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
      <div className="w-full max-w-2xl">
        <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-8">
          <div className="text-center mb-8">
            <h1 className="text-3xl font-bold text-gray-900 mb-2">
              Vérification de votre compte
            </h1>
            <p className="text-gray-600">
              Pour sécuriser votre compte, veuillez vérifier votre email et votre téléphone
            </p>
          </div>

          {/* Messages */}
          {error && (
            <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-start gap-3">
              <AlertCircle className="w-5 h-5 text-red-600 shrink-0 mt-0.5" />
              <p className="text-sm text-red-800">{error}</p>
            </div>
          )}

          {success && (
            <div className="mb-6 p-4 bg-green-50 border border-green-200 rounded-lg flex items-start gap-3">
              <CheckCircle2 className="w-5 h-5 text-green-600 shrink-0 mt-0.5" />
              <p className="text-sm text-green-800">{success}</p>
            </div>
          )}

          <div className="space-y-8">
            {/* Vérification Email */}
            {!status.email_verified && (
              <div className="border border-gray-200 rounded-lg p-6">
                <div className="flex items-center gap-3 mb-4">
                  <div className="p-2 bg-blue-100 rounded-lg">
                    <Mail className="w-5 h-5 text-blue-600" />
                  </div>
                  <div>
                    <h3 className="font-semibold text-gray-900">Vérification Email</h3>
                    <p className="text-sm text-gray-600">{user?.email}</p>
                  </div>
                </div>

                <form onSubmit={handleVerifyEmail} className="space-y-4">
                  <div>
                    <Label htmlFor="emailCode">Code de vérification (6 chiffres)</Label>
                    <Input
                      id="emailCode"
                      type="text"
                      maxLength={6}
                      value={emailCode}
                      onChange={(e) => setEmailCode(e.target.value.replace(/\D/g, ''))}
                      placeholder="123456"
                      className="text-center text-2xl tracking-widest"
                      required
                    />
                  </div>

                  <div className="flex gap-3">
                    <Button
                      type="submit"
                      disabled={loading || emailCode.length !== 6}
                      className="flex-1 bg-[#FF5722] hover:bg-[#E64A19]"
                    >
                      Vérifier Email
                    </Button>
                    <Button
                      type="button"
                      variant="outline"
                      onClick={handleResendEmail}
                      disabled={loading}
                    >
                      Renvoyer
                    </Button>
                  </div>
                </form>
              </div>
            )}

            {status.email_verified && (
              <div className="border border-green-200 bg-green-50 rounded-lg p-6">
                <div className="flex items-center gap-3">
                  <CheckCircle2 className="w-6 h-6 text-green-600" />
                  <div>
                    <h3 className="font-semibold text-green-900">Email vérifié</h3>
                    <p className="text-sm text-green-700">{user?.email}</p>
                  </div>
                </div>
              </div>
            )}

            {/* Vérification Téléphone */}
            {!status.phone_verified && (
              <div className="border border-gray-200 rounded-lg p-6">
                <div className="flex items-center gap-3 mb-4">
                  <div className="p-2 bg-green-100 rounded-lg">
                    <Phone className="w-5 h-5 text-green-600" />
                  </div>
                  <div>
                    <h3 className="font-semibold text-gray-900">Vérification Téléphone</h3>
                    <p className="text-sm text-gray-600">{user?.phone_number}</p>
                  </div>
                </div>

                <form onSubmit={handleVerifyPhone} className="space-y-4">
                  <div>
                    <Label htmlFor="phoneCode">Code de vérification (6 chiffres)</Label>
                    <Input
                      id="phoneCode"
                      type="text"
                      maxLength={6}
                      value={phoneCode}
                      onChange={(e) => setPhoneCode(e.target.value.replace(/\D/g, ''))}
                      placeholder="123456"
                      className="text-center text-2xl tracking-widest"
                      required
                    />
                  </div>

                  <div className="flex gap-3">
                    <Button
                      type="submit"
                      disabled={loading || phoneCode.length !== 6}
                      className="flex-1 bg-[#FF5722] hover:bg-[#E64A19]"
                    >
                      Vérifier Téléphone
                    </Button>
                    <Button
                      type="button"
                      variant="outline"
                      onClick={handleResendPhone}
                      disabled={loading}
                    >
                      Renvoyer
                    </Button>
                  </div>
                </form>
              </div>
            )}

            {status.phone_verified && (
              <div className="border border-green-200 bg-green-50 rounded-lg p-6">
                <div className="flex items-center gap-3">
                  <CheckCircle2 className="w-6 h-6 text-green-600" />
                  <div>
                    <h3 className="font-semibold text-green-900">Téléphone vérifié</h3>
                    <p className="text-sm text-green-700">{user?.phone_number}</p>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Actions */}
          <div className="mt-8 pt-6 border-t border-gray-200">
            <div className="flex justify-between items-center">
              <Button
                variant="ghost"
                onClick={handleSkip}
                className="text-gray-600"
              >
                Passer cette étape
              </Button>
              
              {status.email_verified && status.phone_verified && (
                <Button
                  onClick={() => router.push('/preferences')}
                  className="bg-[#FF5722] hover:bg-[#E64A19]"
                >
                  Continuer
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}